func ListProducts(db *sql.DB, orderBy string, sortDir string) ([]Product, error) {
	// Validate orderBy column name
	validColumns := map[string]bool{
		"id":    true,
		"name":  true,
		"price": true,
	}
	if !validColumns[orderBy] {
		return nil, fmt.Errorf("invalid column name: %s", orderBy)
	}

	// Validate sort direction (case-insensitive)
	sortDirUpper := strings.ToUpper(sortDir)
	if sortDirUpper != "ASC" && sortDirUpper != "DESC" {
		return nil, fmt.Errorf("invalid sort direction: %s", sortDir)
	}

	query := fmt.Sprintf("SELECT id, name, price FROM products ORDER BY %s %s", orderBy, sortDirUpper)
	rows, err := db.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price); err != nil {
			return nil, err
		}
		products = append(products, p)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return products, nil
}

